from pathlib import Path

path = Path('index.html')
text = path.read_text(encoding='utf-8')

anchor = '''      .print-muted { color: #697a8c; }\n'''
overrides = '''      .print-muted { color: #697a8c; }\n\n      /* PDF pagination and layout hardening: keep the commercial proposal to two A4 pages. */\n      .print-proposal { font-size: 8.5pt; line-height: 1.32; }\n      .print-page {\n        min-height: 297mm;\n        padding: 10mm 11mm 11mm;\n        page-break-inside: avoid;\n        break-inside: avoid-page;\n      }\n      .print-brandbar { height: 3mm; margin: -10mm -11mm 6mm; }\n      .print-header { gap: 7mm; padding-bottom: 4mm; }\n      .print-logo { width: 16mm; height: 16mm; }\n      .print-brand { gap: 3mm; }\n      .print-brand h1 { font-size: 14.5pt; }\n      .print-brand p { margin-top: .8mm; font-size: 6.8pt; }\n      .print-docmeta { font-size: 6.8pt; }\n      .print-docmeta strong { font-size: 7.7pt; }\n      .print-title { margin: 5mm 0 1.8mm; font-size: 20pt; }\n      .print-intro { margin-bottom: 4mm; font-size: 8.1pt; line-height: 1.35; }\n      .print-budget-hero { gap: 3mm; margin-bottom: 4mm; }\n      .print-budget-main { padding: 4.5mm; border-radius: 3.5mm; }\n      .print-budget-main small { margin-bottom: 1.4mm; font-size: 6.5pt; }\n      .print-budget-main strong { font-size: 24pt; }\n      .print-budget-main span { margin-top: 1.8mm; font-size: 7.3pt; }\n      .print-budget-side { gap: 1.8mm; }\n      .print-stat { padding: 2.4mm 3mm; }\n      .print-stat span { font-size: 6.2pt; }\n      .print-stat strong { margin-top: .6mm; font-size: 9.5pt; }\n      .print-section { margin-top: 3.3mm; }\n      .print-section-title { margin-bottom: 2mm; padding-bottom: 1.2mm; font-size: 10.5pt; }\n      .print-calc-grid { gap: 1.2mm 4mm; }\n      .print-calc-row { gap: 3mm; padding: 1.55mm 0; }\n      .print-calc-total { margin-top: .6mm; padding: 2.4mm 3mm; }\n      .print-calc-total strong { font-size: 13.5pt; }\n\n      /* Nine scope items fit naturally as a compact 3 x 3 executive grid. */\n      .print-includes { grid-template-columns: repeat(3, 1fr); gap: 1.8mm; }\n      .print-include { padding: 2.1mm; border-radius: 2.4mm; }\n      .print-include b { font-size: 7.4pt; line-height: 1.2; }\n      .print-include span { margin-top: .55mm; font-size: 6.65pt; line-height: 1.27; }\n      .print-note { margin-top: 2.5mm; padding: 2.4mm 3mm; font-size: 6.8pt; line-height: 1.32; }\n\n      /* Page 2: compact the tariff table and use horizontal space for conditions. */\n      .print-table { table-layout: fixed; margin-top: 1.4mm; font-size: 7pt; line-height: 1.25; }\n      .print-table th { padding: 1.8mm; font-size: 6.4pt; }\n      .print-table td { padding: 1.8mm; }\n      .print-table th:nth-child(1), .print-table td:nth-child(1) { width: 14%; }\n      .print-table th:nth-child(2), .print-table td:nth-child(2) { width: 12%; }\n      .print-table th:nth-child(3), .print-table td:nth-child(3) { width: 20%; }\n      .print-table th:nth-child(4), .print-table td:nth-child(4) { width: 54%; }\n      .print-two-col { gap: 3.5mm; }\n      .print-box { padding: 2.8mm; border-radius: 2.5mm; }\n      .print-box h3 { margin-bottom: 1.5mm; font-size: 9pt; line-height: 1.2; }\n      .print-list { padding-left: 4mm; font-size: 7pt; line-height: 1.3; }\n      .print-list li { margin-bottom: 1mm; }\n      .print-page:nth-of-type(2) > .print-section.print-box { break-inside: auto; page-break-inside: auto; }\n      .print-page:nth-of-type(2) > .print-section.print-box .print-list {\n        columns: 2;\n        column-gap: 5mm;\n        column-fill: balance;\n      }\n      .print-page:nth-of-type(2) > .print-section.print-box .print-list li { break-inside: avoid; page-break-inside: avoid; }\n      .print-contact { margin-top: 3.2mm; padding: 3mm 4mm; }\n      .print-contact strong { font-size: 9.5pt; }\n      .print-contact span { margin-top: .7mm; font-size: 7pt; }\n      .print-footer { left: 11mm; right: 11mm; bottom: 4.5mm; padding-top: 1.8mm; font-size: 6.1pt; }\n'''

if 'PDF pagination and layout hardening' not in text:
    if anchor not in text:
        raise SystemExit('print CSS anchor not found')
    text = text.replace(anchor, overrides, 1)

path.write_text(text, encoding='utf-8')
print('PDF pagination patch applied')
